function rebuildAll(){for(const g of chunks.values()){scene.remove(g);g.children.forEach(m=>m.geometry.dispose())}chunks.clear();dirty.clear();for(let x=0;x<W/CH;x++)for(let z=0;z<W/CH;z++)buildChunk(x,z)}
function buildChunk(cx,cz){if(cx<0||cz<0||cx>=W/CH||cz>=W/CH)return;let key=`${cx},${cz}`,old=chunks.get(key);if(old){scene.remove(old);old.children.forEach(m=>m.geometry.dispose())}let p=[],n=[],uv=[],col=[],ix=[],wp=[],wn=[],wi=[];for(let x=cx*CH;x<Math.min(W,(cx+1)*CH);x++)for(let z=cz*CH;z<Math.min(W,(cz+1)*CH);z++)for(let y=0;y<H;y++){const id=getB(x,y,z);if(!id)continue;const water=id===13;let plant=id===17,lantern=id===22;let growth=crops[`${x},${y},${z}`]||0;for(const f of faces){let next=getB(x+f.n[0],y+f.n[1],z+f.n[2]);if(water?(next===13||f.n[1]!==1):((solid(next)&&next!==12)||id===12&&next===12))continue;let pos=water?wp:p,norm=water?wn:n,indices=water?wi:ix,base=pos.length/3;let texture=id===1&&f.n[1]!==1?2:id===15&&f.n[1]!==1?3:id;let u0=(texture%8)*16/128,v0=1-(Math.floor(texture/8)+1)*16/64;let ut=[0,1,0,1],vt=[0,0,1,1];for(let j=0;j<4;j++){let a=f.v[j],scale=lantern?.35:plant?.72:1,hh=lantern?.55:plant?.24+growth*.62:water?.86:1;pos.push(x+.5+(a[0]-.5)*scale,y+a[1]*hh,z+.5+(a[2]-.5)*scale);norm.push(...f.n);if(!water){uv.push(u0+.002+ut[j]*(.125-.004),v0+.004+vt[j]*(.25-.008));let l=f.light;if(id===1&&f.n[1]!==1)l*=.85;if(id===6){let b=biomeAt(x,z);col.push(l*(b===2?.65:1),l*(b===2?.9:1),l*(b===2?.82:1))}else if(id===17&&growth<.8)col.push(l*.68,l,l*.68);else col.push(l,l,l)}}indices.push(base,base+1,base+2,base+2,base+1,base+3)}}let group=new THREE.Group();function mesh(pos,norm,ind,material,uvs,colors){if(!pos.length)return;let geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.setAttribute('normal',new THREE.Float32BufferAttribute(norm,3));if(uvs)geo.setAttribute('uv',new THREE.Float32BufferAttribute(uvs,2));if(colors)geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.setIndex(ind);geo.computeBoundingSphere();group.add(new THREE.Mesh(geo,material))}mesh(p,n,ix,blockMaterial,uv,col);mesh(wp,wn,wi,waterMaterial);chunks.set(key,group);scene.add(group)}
const cubeGeo=new THREE.BoxGeometry(1,1,1),materials={};function mat(c,emissive=false){const k=c+emissive;if(!materials[k])materials[k]=emissive?new THREE.MeshBasicMaterial({color:c}):new THREE.MeshLambertMaterial({color:c});return materials[k]}
