function voxelRay(origin,direction,max=6){let x=Math.floor(origin.x),y=Math.floor(origin.y),z=Math.floor(origin.z),sx=Math.sign(direction.x),sy=Math.sign(direction.y),sz=Math.sign(direction.z),dx=Math.abs(1/direction.x),dy=Math.abs(1/direction.y),dz=Math.abs(1/direction.z),tx=direction.x===0?Infinity:(sx>0?x+1-origin.x:origin.x-x)*dx,ty=direction.y===0?Infinity:(sy>0?y+1-origin.y:origin.y-y)*dy,tz=direction.z===0?Infinity:(sz>0?z+1-origin.z:origin.z-z)*dz,dist=0,n=[0,0,0];for(let step=0;step<100&&dist<=max;step++){let id=getB(x,y,z);if(id&&id!==13)return{x,y,z,id,n,dist};if(tx<ty&&tx<tz){x+=sx;dist=tx;tx+=dx;n=[-sx,0,0]}else if(ty<tz){y+=sy;dist=ty;ty+=dy;n=[0,-sy,0]}else{z+=sz;dist=tz;tz+=dz;n=[0,0,-sz]}}return null}
function collides(x,y,z){const r=.29;for(let xx=Math.floor(x-r);xx<=Math.floor(x+r);xx++)for(let zz=Math.floor(z-r);zz<=Math.floor(z+r);zz++)for(let yy=Math.floor(y+.05);yy<=Math.floor(y+1.74);yy++)if(solid(getB(xx,yy,zz)))return true;return x<.4||z<.4||x>W-.4||z>W-.4}
function addItem(id,n=1,notify=true,opts={}){if(!items[id]||!game)return false;let inv=game.inv,it=items[id];let remaining=n;let capacity=inv.reduce((total,s)=>total+(!s?(it.dur?1:99):s.id===id&&!it.dur?99-s.n:0),0);if(capacity<n){if(notify){toast('Pack full — your find is on the ground.');spawnDrop(id,n,game.p.x,game.p.y+.6,game.p.z,opts)}return false}if(!it.dur){for(let s of inv)if(s?.id===id&&s.n<99){let take=Math.min(99-s.n,remaining);s.n+=take;remaining-=take;if(!remaining)break}}while(remaining>0){let i=inv.findIndex(s=>!s);if(i<0){if(notify)toast('Pack full — free a slot to collect this.');return n!==remaining}let take=it.dur?1:Math.min(99,remaining);inv[i]={id,n:take,...(it.dur?{dur:it.dur}:{}),...opts};remaining-=take}if(notify)toast(`+${n} ${it.name}`);game.stats.collected+=n;game.flags[id]=true;questDirty=true;refreshHotbar();return true}
function count(id){return game?game.inv.reduce((a,s)=>a+(s?.id===id?s.n:0),0):0}function consume(id,n=1){if(count(id)<n)return false;for(let i=0;i<game.inv.length&&n;i++){let s=game.inv[i];if(s?.id===id){let v=Math.min(s.n,n);s.n-=v;n-=v;if(!s.n)game.inv[i]=null}}refreshHotbar();return true}
function selected(){return game?.inv[game.sel]}function wearTool(n=1){const s=selected();if(!s||!items[s.id].dur)return;if(s.enchant==='Unbreaking')n*=.45;s.dur-=n;if(s.dur<=0){toast(`${items[s.id].name} broke`);game.inv[game.sel]=null;updateHeld();sound('break')}refreshHotbar()}
function setSlot(n){if(!game)return;game.sel=(n+9)%9;mining=null;mouseDown=false;refreshHotbar();updateHeld();sound('click')}
function stationNear(name){const id={bench:19,furnace:18,enchanter:20}[name];if(!game)return false;let p=game.p;for(let x=Math.floor(p.x)-5;x<=Math.floor(p.x)+5;x++)for(let z=Math.floor(p.z)-5;z<=Math.floor(p.z)+5;z++)for(let y=Math.floor(p.y)-3;y<=Math.floor(p.y)+3;y++)if(getB(x,y,z)===id)return true;return false}
function canCraft(r){return Object.entries(r.need).every(([id,n])=>count(id)>=n)&&(!r.station||stationNear(r.station))}
function craft(i){const r=recipes[i];if(!r||!canCraft(r))return;let free=game.inv.some(s=>!s)||game.inv.some(s=>s?.id===r.out&&!items[r.out].dur&&s.n+r.n<=99)||Object.entries(r.need).some(([id,n])=>game.inv.some(s=>s?.id===id&&s.n<=n));if(!free){toast('Make room in your pack first.');return}Object.entries(r.need).forEach(([id,n])=>consume(id,n));addItem(r.out,r.n);game.stats.crafted++;gainXP(3);game.flags.crafted=true;sound('craft');UI.renderInventory();questDirty=true;saveGame()}
const enchantments=[{name:'Efficiency',cost:12,desc:'Mine 65% faster. Pickaxe, axe or hoe.'},{name:'Sharpness',cost:15,desc:'+50% attack damage. Any weapon or tool.'},{name:'Unbreaking',cost:10,desc:'Tools last more than twice as long.'}];
function enchant(i){const e=enchantments[i],s=selected();if(!stationNear('enchanter')||!s||!items[s.id].tool||game.xp<e.cost||s.enchant)return;if(i===0&&!['pick','axe','hoe'].includes(items[s.id].tool)){toast('Efficiency requires a pickaxe, axe, or hoe.');return}game.xp-=e.cost;s.enchant=e.name;game.flags.enchanted=true;sound('level');toast(`${e.name} imbued!`,'gold');UI.renderInventory();refreshHotbar();saveGame()}
function fuelValue(id){return id==='coal'?3:1}function smelt(id){let result={ironore:'iron',rawmeat:'meat',sand:'glass'}[id];if(!result||!stationNear('furnace')||!count(id))return;let fuel=count('coal')?'coal':count('log')?'log':count('planks')?'planks':null;if(!fuel){toast('Smelting needs coal, a log, or planks.');return}let mKey=nearestMachine(18);if(!mKey)return;let m=machines[mKey]||(machines[mKey]={queue:[],progress:0});if(m.queue.length>=8){toast('This furnace is full.');return}let n=Math.min(count(id),fuelValue(fuel));consume(id,n);consume(fuel,1);m.queue.push({id:result,n,time:id==='ironore'?10:7});game.flags.smelted=true;sound('craft');UI.renderInventory();saveGame()}
