function processMachines(dt){for(let k in machines){let m=machines[k],xyz=k.split(',').map(Number);if(getB(...xyz)!==18)continue;if(!m.queue.length)continue;m.progress+=dt;if(m.progress>=m.queue[0].time){let job=m.queue.shift();m.progress=0;spawnDrop(job.id,job.n,xyz[0]+.5,xyz[1]+1.2,xyz[2]+.5);if(game&&Math.hypot(game.p.x-xyz[0],game.p.z-xyz[2])<8)toast(`Furnace ready: ${job.n} ${items[job.id].name}`);emit(xyz[0]+.5,xyz[1]+1,xyz[2]+.5,'#ecc177',7)}}}
