function persistMeta(){safeStore.set('vw-meta',JSON.stringify(meta))}
const questDefs=[{title:'Every adventure starts small',desc:'Gather 3 oak logs. Hold left click on a tree. Wood is the beginning of everything.',test:()=>game.stats.logs>=3,progress:()=>Math.min(3,game.stats.logs)/3,foot:'GATHER 3 OAK LOGS',reward:['apple',3]},{title:'A place to make things',desc:'E → Craft: turn logs into planks, craft a bench, then place it with right click.',test:()=>game.flags.benchPlaced,foot:'PLACE A CRAFTING BENCH',reward:['coal',3]},{title:'Beneath the surface',desc:'The mine is northwest of camp (38, 48). Make a stone pickaxe to mine iron.',test:()=>game.flags.ironore,foot:'COLLECT RAW IRON',reward:['feather',3]},{title:'Bring the fire',desc:'Craft and place a furnace. Smelt iron using coal; collect the ingots beside it.',test:()=>game.flags.iron,foot:'SMELT YOUR FIRST IRON',reward:['apple',4]},{title:'Life takes root',desc:'Craft a hoe. F tills grass, then F with seeds plants wheat. Mine ripe crops to harvest.',test:()=>game.flags.harvested,foot:'HARVEST A RIPE CROP',reward:['wool',3]},{title:'A light in the deep',desc:'Craft an iron pickaxe. Diamonds await at the end of the starter mine and deep caves.',test:()=>game.flags.diamond,foot:'DISCOVER DIAMOND',reward:['iron',3]},{title:'An ancient calling',desc:'Craft a Sky Sigil: 3 diamonds, 4 iron, 4 coal. Prepare armor, a bow, arrows and food.',test:()=>game.flags.sigil,foot:'CRAFT THE SKY SIGIL',reward:['arrow',36]},{title:'Wake the sleeping sky',desc:'Take the sigil to the ancient altar at 42, 24. Face it and press F to summon the Wyrm.',test:()=>game.flags.bossSummoned,foot:'AWAKEN THE VERDANT WYRM',reward:['potion',3]},{title:'The last legend',desc:'Shoot while it circles. When it lands, attack with a sword. Dodge violet breath and keep eating.',test:()=>game.flags.victory,foot:'DEFEAT THE VERDANT WYRM',reward:['scale',1]}];
function updateQuests(){if(!game)return;for(let i=0;i<questDefs.length;i++){if(!game.quests.includes(i)&&questDefs[i].test()){game.quests.push(i);const q=questDefs[i];toast(`Journey complete · ${q.title}`,'gold');addItem(q.reward[0],q.reward[1],false);gainXP(10);sound('quest');}}let qi=questDefs.findIndex((q,i)=>!game.quests.includes(i));if(qi<0){$('quest').innerHTML='<div class="eyebrow">THE WORLD IS YOURS</div><h4>Keeper of the wild</h4><p>The Wyrm has fallen. Build a home, master enchantments, or explore the four biomes.</p>';return}const q=questDefs[qi];$('quest').innerHTML=`<div class="eyebrow">YOUR JOURNEY <span style="float:right;color:#95b08c">${game.quests.length}/9</span></div><h4>${q.title}</h4><p>${q.desc}</p><div class="progress"><span style="width:${q.progress?q.progress()*100:8}%"></span></div><div class="qfoot"><span>${q.foot}</span><span>J ↗</span></div>`;questDirty=false}
function makeGame(){return{p:{x:43.5,y:11,z:56.5,vy:0,yaw:0,pitch:0,hp:100,food:100,grounded:false,armor:0,armorName:'None',safe:4,fallY:11},inv:Array(36).fill(null),sel:0,xp:0,totalXP:0,level:1,time:.31,day:1,elapsed:0,flags:{},quests:[],stats:{mined:0,placed:0,kills:0,crafted:0,collected:0,logs:0,damage:0,level:1},home:{x:43.5,y:11,z:56.5},won:false,deathCause:'The wilderness',weather:0,visited:[]}}
function clearEntities(){for(const m of mobs)scene.remove(m.group);for(const d of drops)scene.remove(d.mesh);for(const p of particles)scene.remove(p.mesh);for(const p of projectiles)scene.remove(p.mesh);if(boss)scene.remove(boss.group);mobs=[];drops=[];particles=[];projectiles=[];boss=null}
function newGame(){if(state==='loading')return;Audio.start();state='loading';$('loading').classList.remove('hidden');$('overlay').classList.add('hidden');let nextSeed=$('seedInput').value.trim()||'WILDFLOWER';requestAnimationFrame(()=>{setTimeout(()=>{try{clearEntities();generateWorld(nextSeed);game=makeGame();game.p.y=groundAt(43,56);game.home.y=game.p.y;game.p.fallY=game.p.y;meta.runs++;persistMeta();addItem('pick1',1,false);addItem('axe1',1,false);addItem('sword1',1,false);addItem('apple',5,false);addItem('planks',12,false);addItem('torch',8,false);addItem('seeds',6,false);addItem('dirt',12,false);addItem('hoe1',1,false);for(let i=0;i<14;i++)spawnMob(['pig','cow','sheep','chicken'][i%4],32+rng()*21,51+rng()*17);startPlay();if(!saveGame())toast('Local saves are blocked in this preview. Download the HTML to keep your world.','gold');toast('Welcome to Wildflower Meadow. Make it yours.');}catch(e){fatal(e)}},30)})}
function startPlay(){state='playing';previousState='playing';$('title').classList.add('hidden');$('overlay').classList.add('hidden');$('hud').classList.remove('hidden');$('loading').classList.add('hidden');$('hint').classList.remove('hidden');$('bossHud').classList.toggle('hidden',!boss);keys={};mouseDown=false;mining=null;saveTimer=0;hudTimer=0;attackCD=0;interactCD=0;waterTime=0;heldSwing=0;hurtFlash=0;shake=0;spawnTimer=5;$('toasts').innerHTML='';$('floating').innerHTML='';$('damageVignette').style.opacity=0;Audio.step=0;if(Audio.ctx)Audio.next=Audio.ctx.currentTime+.4;frameTime=performance.now();questDirty=true;refreshHotbar();updateHeld();updateCamera(0);updateQuests();lockPointer()}
function saveGame(){if(!game||game.p.hp<=0)return false;let data={v:1,seed,difficulty:settings.difficulty,game,mods,crops,machines,mobs:mobs.map(m=>({type:m.type,x:m.x,y:m.y,z:m.z,hp:m.hp,tame:m.tame,shorn:m.shorn||false,egg:m.egg})),drops:drops.map(d=>({id:d.id,n:d.n,x:d.mesh.position.x,y:d.mesh.position.y,z:d.mesh.position.z,opts:d.opts||{}})),boss:boss?{hp:boss.hp,max:boss.max,t:boss.t}:null};let ok=safeStore.set('vw-save',JSON.stringify(data));if(ok)$('continueButton').classList.remove('hidden');return ok}
function loadGame(){const raw=safeStore.get('vw-save');if(!raw)return;try{const data=JSON.parse(raw);if(!data.game||data.v!==1)throw new Error('Save version not supported');Audio.start();clearEntities();generateWorld(data.seed);game=data.game;game.p.safe=4;settings.difficulty=data.difficulty;mods=data.mods||{};for(const i in mods)world[+i]=mods[i];crops=data.crops||{};machines=data.machines||{};rebuildAll();buildDecor();for(const m of data.mobs||[]){let entity=spawnMob(m.type,m.x,m.z,m.hp);if(entity){entity.tame=!!m.tame;entity.shorn=m.shorn||false;entity.egg=m.egg??45}}for(const d of data.drops||[])spawnDrop(d.id,d.n,d.x,d.y,d.z,d.opts||{});if(data.boss){createBoss();boss.hp=data.boss.hp;boss.max=data.boss.max;boss.t=data.boss.t}$('seedInput').value=data.seed;setDifficulty(settings.difficulty);startPlay();toast('Welcome back. Your wilderness remembers.')}catch(e){toast('This save could not be loaded. Start a new expedition.');console.error(e);state='title';$('loading').classList.add('hidden')}}
function goTitle(){saveGame();releasePointer();state='title';game=null;clearEntities();held.visible=false;selection.visible=false;$('hud').classList.add('hidden');$('overlay').classList.add('hidden');$('title').classList.remove('hidden');$('continueButton').classList.toggle('hidden',!safeStore.get('vw-save'))}
function setDifficulty(d){settings.difficulty=d;document.querySelectorAll('[data-d]').forEach(b=>b.classList.toggle('active',+b.dataset.d===d));$('diffLabel').textContent=['Room to breathe. Still a dragon.','A little danger. A lot of wonder.','The wilderness bites back.'][d];saveSettings();if(game)toast(['Peaceful · no night monsters, gentle hunger','Survival · a balanced wilderness','Wild · stronger monsters, faster hunger'][d])}function saveSettings(){safeStore.set('vw-settings',JSON.stringify(settings));if(scene)scene.fog.far=settings.view;Audio.volume()}
function toast(text,kind=''){const el=document.createElement('div');el.className='toast '+kind;el.textContent=text;$('toasts').appendChild(el);while($('toasts').children.length>5)$('toasts').firstChild.remove();setTimeout(()=>{el.style.opacity=0;setTimeout(()=>el.remove(),250)},3600)}
function floating(text,pos,color='#f5efce'){let v=pos.clone().project(camera);if(v.z>1)return;const e=document.createElement('div');e.className='float';e.textContent=text;e.style.left=((v.x*.5+.5)*innerWidth)+'px';e.style.top=((-v.y*.5+.5)*innerHeight)+'px';e.style.color=color;$('floating').appendChild(e);setTimeout(()=>e.remove(),950)}
function refreshHotbar(){if(!game)return;const bar=$('hotbar');bar.innerHTML=game.inv.slice(0,9).map((s,i)=>`<div class="slot ${game.sel===i?'selected':''}" onclick="setSlot(${i})" title="${s?items[s.id].name:'Empty slot'}"><span class="num">${i+1}</span>${s?`<img class="item-icon" src="${itemIcon(s.id)}" alt="${items[s.id].name}">${s.n>1?`<span class="count">${s.n}</span>`:''}${s.dur?`<span class="durability"><i style="width:${s.dur/items[s.id].dur*100}%;background:${s.enchant?'#c0a5e6':'#c8ec83'}"></i></span>`:''}`:''}</div>`).join('');const s=selected();$('selectedLabel').textContent=s?items[s.id].name+(s.enchant?' ✦':''):'Empty hand';$('levelLabel').textContent=`LV ${game.level} · ${Math.floor(game.xp)} ESSENCE`;$('xpFill').style.width=((game.totalXP-(game.level-1)**2*10)/((game.level**2-(game.level-1)**2)*10))*100+'%';updateHeld()}
// Synthesized ambience and tactile effects, no audio assets.
const Audio={ctx:null,gain:null,musicGain:null,muted:false,step:0,next:0,start(){try{if(!this.ctx){this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.gain=this.ctx.createGain();this.gain.connect(this.ctx.destination);this.musicGain=this.ctx.createGain();this.musicGain.gain.value=.12;this.musicGain.connect(this.gain);this.next=this.ctx.currentTime+.3;this.volume()}if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{})}catch(e){}},volume(){if(this.gain)this.gain.gain.setTargetAtTime(this.muted?0:settings.volume,this.ctx.currentTime,.08)},tone(freq,duration,type='sine',vol=.1,slide=0,delay=0,music=false){if(!this.ctx||this.muted)return;let now=this.ctx.currentTime+delay,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,now);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(25,freq+slide),now+duration);g.gain.setValueAtTime(0,now);g.gain.linearRampToValueAtTime(vol,now+.008);g.gain.exponentialRampToValueAtTime(.0001,now+duration);o.connect(g);g.connect(music?this.musicGain:this.gain);o.start(now);o.stop(now+duration+.03);o.onended=()=>{o.disconnect();g.disconnect()}},noise(duration=.12,vol=.07){if(!this.ctx||this.muted)return;let count=Math.floor(this.ctx.sampleRate*duration),buffer=this.ctx.createBuffer(1,count,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<count;i++)data[i]=(Math.random()*2-1)*(1-i/count);let s=this.ctx.createBufferSource(),g=this.ctx.createGain(),filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1200;s.buffer=buffer;g.gain.value=vol;s.connect(filter);filter.connect(g);g.connect(this.gain);s.start();s.onended=()=>{s.disconnect();g.disconnect();filter.disconnect()}},update(){if(!this.ctx||this.muted||state==='title'||state==='loading')return;let now=this.ctx.currentTime;if(this.next<now){const notes=boss?[130.81,155.56,196,233.08,261.63,196,155.56,174.61]:[196,246.94,293.66,369.99,329.63,293.66,246.94,220];let i=this.step++%notes.length;this.tone(notes[i],boss?.65:1.8,'sine',.35,0,0,true);if(i%4===0)this.tone(notes[i]/2,2.6,'triangle',.22,0,0,true);if(boss)this.noise(.035,.018);this.next=now+(boss?.4:.86)}}};
function sound(type){Audio.start();if(type==='mine'){Audio.noise(.07,.1);Audio.tone(120,.06,'triangle',.08,-60)}else if(type==='break'){Audio.noise(.18,.16);Audio.tone(95,.1,'triangle',.1,-45)}else if(type==='place'){Audio.noise(.055,.07);Audio.tone(160,.08,'sine',.12,-70)}else if(type==='hit'){Audio.noise(.1,.14);Audio.tone(100,.12,'sawtooth',.06,-50)}else if(type==='hurt'){Audio.tone(160,.18,'triangle',.2,-100);Audio.noise(.16,.1)}else if(type==='pickup'){Audio.tone(660,.12,'sine',.08,180)}else if(type==='craft'){[330,440,660].forEach((n,i)=>Audio.tone(n,.25,'triangle',.1,0,i*.065))}else if(type==='level'||type==='quest'){[392,494,587,784].forEach((n,i)=>Audio.tone(n,.5,'sine',.13,0,i*.1))}else if(type==='bow'){Audio.noise(.1,.08);Audio.tone(300,.13,'triangle',.1,-180)}else if(type==='explode'){Audio.noise(.65,.35);Audio.tone(70,.6,'sawtooth',.14,-40)}else if(type==='eat'){Audio.noise(.075,.08);Audio.tone(260,.1,'triangle',.08,50)}else if(type==='roar'){Audio.tone(60,1.3,'sawtooth',.18,-30);Audio.noise(.8,.12)}else Audio.tone(440,.045,'sine',.035)}
function toggleMute(){Audio.start();Audio.muted=!Audio.muted;Audio.volume();$('muteButton').textContent=Audio.muted?'×':'♪';if(state==='settings')UI.renderSettings()}
// All menus are functional and leave the simulation paused.
const UI={open(type,html,wide=false){if(state==='playing'){saveGame();previousState='playing'}else if(state==='title')previousState='title';state=type;mouseDown=false;keys={};releasePointer();$('overlay').classList.remove('hidden');$('modal').className='modal'+(wide?' wide':'');$('modal').innerHTML=html;held.visible=false;selection.visible=false},head(k,title,close='UI.close()'){return`<div class="modal-head"><div><div class="eyebrow">${k}</div><h2>${title}</h2></div><button class="close" onclick="${close}" aria-label="Close">×</button></div>`},close(){if(previousState==='playing'&&game){state='playing';$('overlay').classList.add('hidden');updateHeld();keys={};mouseDown=false;lockPointer()}else{state='title';$('overlay').classList.add('hidden')}},pause(){if(!game)return;this.open('pause',this.head('TAKE A BREATHER','The wild can wait.')+`<p>Your expedition is paused. Settle in, stretch your legs, then pick up where you left off.</p><div class="divider"></div><div class="menu-stack"><button class="primary" onclick="UI.close()">Back to the wilderness <span>→</span></button><button class="secondary" onclick="UI.settings()">Settings & difficulty</button><button class="secondary" onclick="UI.help()">Field guide & controls</button><button class="secondary" onclick="UI.journal()">Your journey</button><button class="secondary" onclick="goTitle()">Save & return to title</button></div><p style="font-size:10px;text-align:center">${escapeHTML(seed)} · DAY ${game.day} · ${biomeNames[biomeAt(game.p.x,game.p.z)]}</p>`)},settings(){this.open('settings','');this.renderSettings()},renderSettings(){$('modal').innerHTML=this.head('MAKE YOURSELF AT HOME','Settings')+`<div class="setting-row"><span>Adventure difficulty</span><div class="segmented">${['Peaceful','Survival','Wild'].map((v,i)=>`<button class="${settings.difficulty===i?'active':''}" data-d="${i}" onclick="setDifficulty(${i})">${v}</button>`).join('')}</div></div><p style="font-size:11px">Peaceful removes night monsters. The dragon remains in every mode. Difficulty changes apply immediately.</p><div class="setting-row"><span>Master volume</span><input aria-label="Master volume" type="range" min="0" max="1" step=".01" value="${settings.volume}" oninput="settings.volume=+this.value;saveSettings()"></div><div class="setting-row"><span>Mute audio</span><input type="checkbox" ${Audio.muted?'checked':''} onchange="toggleMute()"></div><div class="setting-row"><span>Look sensitivity</span><input aria-label="Look sensitivity" type="range" min=".3" max="2.5" step=".1" value="${settings.sensitivity}" oninput="settings.sensitivity=+this.value;saveSettings()"></div><div class="setting-row"><span>View distance</span><select aria-label="View distance" onchange="settings.view=+this.value;saveSettings()">${[45,60,70,90].map(n=>`<option ${settings.view===n?'selected':''} value="${n}">${n} blocks</option>`).join('')}</select></div><div class="setting-row"><span>Camera shake</span><input type="checkbox" ${settings.shake?'checked':''} onchange="settings.shake=this.checked;saveSettings()"></div><div class="setting-row"><span>Particles</span><input type="checkbox" ${settings.particles?'checked':''} onchange="settings.particles=this.checked;saveSettings()"></div><button class="primary" style="margin-top:24px" onclick="UI.close()">All set <span>→</span></button>`},help(){this.open('help',this.head('YOUR POCKET FIELD GUIDE','Small beginnings. Big possibilities.')+`<div class="help-grid"><section><h3>Make yourself at home</h3><ol class="guide-list"><li><strong>Gather & craft.</strong> Hold left click to break blocks. E opens your pack. Turn logs into planks, then build and place a crafting bench. Stand within 5 blocks to use a station.</li><li><strong>Dig a little deeper.</strong> The mine at <b>38, 48</b> has coal, iron, and deep diamonds. Wood → stone → iron → diamond. A stone pick mines iron; an iron pick mines diamond. Smelt ore at a furnace.</li><li><strong>Stay fed.</strong> F eats held food. A full stomach slowly heals you. Hunt, gather apples from leaves, or farm. F with a hoe tills grass. F with seeds plants. Ripe wheat turns gold. Crops near water grow faster.</li><li><strong>Prepare for night.</strong> Zombies chase; skeletons shoot; spiders leap; creepers explode; endermen teleport. Place lanterns to discourage spawning. A bedroll skips night and sets home.</li><li><strong>Become a legend.</strong> Craft a Sky Sigil and use it at the altar at <b>42, 24</b>. Fight the three-phase dragon: shoot in flight, strike when it lands. Armor, enchantments and potions help.</li></ol></section><section><div class="help-card"><h3>At your fingertips</h3><p><span class="key">W A S D</span> Move <span class="key">SPACE</span> Jump / swim</p><p><span class="key">MOUSE</span> Look <span class="key">SHIFT</span> Sprint</p><p><span class="key">LMB</span> Mine / attack / shoot</p><p><span class="key">RMB</span> Place block / interact</p><p><span class="key">F</span> Use item, harvest, eat, interact</p><p><span class="key">1–9</span> / scroll Select hotbar slot</p><p><span class="key">E</span> Inventory & crafting</p><p><span class="key">J</span> Journey <span class="key">M</span> Map</p><p><span class="key">Q</span> Drop one held item</p><p><span class="key">ESC</span> / <span class="key">P</span> Pause</p><p style="margin-top:12px">No pointer lock? Drag on the world to look, or use arrow keys. Touch: left pad moves, drag right side to look, ⛏ mines, ＋ places, F uses items.</p></div><div class="help-card" style="margin-top:14px"><h3>A living wilderness</h3><p>Four biomes · four friendly species · five night terrors · a three-phase Wyrm.</p><p>Shear sheep with shears. Feed animals wheat to tame them; tamed chickens lay eggs. Essence from mining and combat pays for enchantments.</p><p>Auto-save every 20 seconds. Closing menus, crafting and pausing also save. Local saves never leave your device.</p></div></section></div><button class="primary" style="margin-top:20px" onclick="UI.close()">Let’s wander <span>→</span></button>`,true)},inventory(tab='craft'){if(!game)return;invTab=tab;selectedInv=-1;this.open('inventory','',true);this.renderInventory()},renderInventory(){if(!game)return;const s=selectedInv>=0?game.inv[selectedInv]:selected();const it=s&&items[s.id];let panel='';if(invTab==='craft'){panel=`<div class="tabs">${['basics','tools','building','combat','farming'].map(t=>`<button class="${category===t?'active':''}" onclick="category='${t}';UI.renderInventory()">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="recipe-header">${stationNear('bench')?'✦ Crafting bench nearby':'Place a crafting bench nearby for advanced recipes.'}</div><div class="recipes">${recipes.map((r,i)=>r.cat!==category?'':`<div class="recipe"><img class="item-icon" src="${itemIcon(r.out)}" alt=""><div class="recipe-detail"><strong>${items[r.out].name}${r.n>1?' ×'+r.n:''}</strong><small>${Object.entries(r.need).map(([id,n])=>`<span class="${count(id)<n?'missing':''}">${items[id].name} ${count(id)}/${n}</span>`).join(' · ')}</small>${r.station&&!stationNear(r.station)?`<small class="missing">Requires nearby ${r.station}</small>`:''}</div><button ${canCraft(r)?'':'disabled'} onclick="craft(${i})">Craft</button></div>`).join('')}</div>`}else if(invTab==='smelt'){let mKey=nearestMachine(18),m=machines[mKey];panel=`<div class="recipe-header">${stationNear('furnace')?'✦ Furnace connected. Coal smelts 3 items; wood smelts 1.':'Place a furnace within 5 blocks to smelt.'}<br>Finished items appear beside the furnace. It works while you explore.</div><div class="recipes">${[['ironore','iron'],['rawmeat','meat'],['sand','glass']].map(([a,b])=>`<div class="recipe"><img class="item-icon" src="${itemIcon(b)}" alt=""><div class="recipe-detail"><strong>${items[b].name}</strong><small>${items[a].name}: ${count(a)} · coal ${count('coal')} / wood ${count('log')+count('planks')}</small></div><button ${stationNear('furnace')&&count(a)&&(count('coal')||count('log')||count('planks'))?'':'disabled'} onclick="smelt('${a}')">Smelt</button></div>`).join('')}<div class="help-card" style="margin-top:14px"><h3>Furnace queue</h3><p>${m?.queue.length?m.queue.map((q,i)=>`${q.n} ${items[q.id].name}${i===0?` — ${Math.ceil(q.time-m.progress)}s remaining`:''}`).join('<br>'):'Nothing smelting. Add a recipe above.'}</p><p>Close your pack to let time pass.</p></div></div>`}else{panel=`<div class="recipe-header">${stationNear('enchanter')?'✦ Enchanting table attuned.':'Place an enchanting table nearby.'}<br>${s&&it?.tool?`Held: ${it.name}${s.enchant?' · '+s.enchant:''}`:'Select a tool in your hotbar before enchanting.'} · ${Math.floor(game.xp)} essence</div><div class="recipes">${enchantments.map((e,i)=>`<div class="recipe"><div class="recipe-detail"><strong>✦ ${e.name}</strong><small>${e.desc}<br>${e.cost} essence · permanent on this tool</small></div><button ${stationNear('enchanter')&&selected()&&items[selected().id].tool&&!selected().enchant&&game.xp>=e.cost?'':'disabled'} onclick="enchant(${i})">Imbue</button></div>`).join('')}<p>One enchantment per tool. Essence is earned by mining ores, combat, crafting, and journey milestones. Spending it does not reduce your level.</p></div>`}let slots=game.inv.map((v,i)=>`<div class="slot ${i===selectedInv?'selected':''}" onclick="inventoryClick(${i})" oncontextmenu="inventoryEquip(event,${i})" title="${v?items[v.id].name:'Empty'}"><span class="num">${i<9?i+1:''}</span>${v?`<img class="item-icon" src="${itemIcon(v.id)}" alt="${items[v.id].name}">${v.n>1?`<span class="count">${v.n}</span>`:''}${v.dur?`<span class="durability"><i style="width:${v.dur/items[v.id].dur*100}%;background:${v.enchant?'#c0a5e6':'#c8ec83'}"></i></span>`:''}`:''}</div>`).join('');$('modal').innerHTML=this.head('CARRY A LITTLE POSSIBILITY','Your expedition pack')+`<div class="inventory-layout"><section><div style="display:flex;justify-content:space-between;margin-bottom:12px"><h3 style="margin:0">Inventory</h3><span class="badge">${game.inv.filter(Boolean).length} / 36 SLOTS</span></div><div class="inventory-grid">${slots}</div><div class="item-info"><h3>${it?it.name:'Room for discovery'} ${s?.enchant?`<span style="color:#bca5e6">✦ ${s.enchant}</span>`:''}</h3><p>${it?(it.tool?`Tier ${it.tier} · ${it.damage||1} damage · ${Math.ceil(s.dur)}/${it.dur} durability`:it.food?`Restores ${it.food} hunger${it.heal?' and '+it.heal+' health':''}. F to eat.`:it.block?'Right click to place. Build something that feels like home.':it.armor?`${Math.round(it.armor*100)}% damage reduction. F to equip.`:it.id==='sigil'?'F at the ancient altar to summon the Wyrm.':'Crafting material. Find a use in the recipes.'): 'Click an item, then another slot to move or swap it.'}</p>${selectedInv>=0&&s?`<button class="text-btn" style="font-size:9px;padding:5px 8px;margin-top:7px" onclick="equipSelected()">Move to active hotbar slot ${game.sel+1}</button>`:''}</div><div class="inventory-stats"><div class="stat"><b>${game.level}</b><small>ADVENTURER LEVEL</small></div><div class="stat"><b>${Math.floor(game.xp)}</b><small>ESSENCE</small></div><div class="stat"><b>${Math.round(game.p.armor*100)}%</b><small>ARMOR PROTECTION</small></div></div><div class="pack-note">First row + first 3 slots of row two = hotbar (1–9).<br>Click two slots to swap. Right-click any item to equip.<br>The world pauses while you’re in your pack.</div></section><section><div class="tabs" style="padding-bottom:14px"><button class="${invTab==='craft'?'active':''}" onclick="invTab='craft';UI.renderInventory()">◇ Craft</button><button class="${invTab==='smelt'?'active':''}" onclick="invTab='smelt';UI.renderInventory()">♨ Smelt</button><button class="${invTab==='enchant'?'active':''}" onclick="invTab='enchant';UI.renderInventory()">✦ Enchant</button></div>${panel}</section></div>`,refreshHotbar()},journal(){if(!game){this.help();return}this.open('journal',this.head('FOLLOW YOUR CURIOSITY','An adventure, one block at a time')+`<p>Journey rewards arrive automatically. You can complete milestones in any order.</p><div class="journal-section">${questDefs.map((q,i)=>`<div class="journal-entry ${game.quests.includes(i)?'complete':''}"><strong><span class="check">${game.quests.includes(i)?'✓':String(i+1).padStart(2,'0')}</span> &nbsp;${q.title}</strong><p>${q.desc}</p><p style="color:#c8ec83">Reward: ${q.reward[1]} ${items[q.reward[0]].name} · 10 essence</p></div>`).join('')}<div class="journal-entry"><strong>THE WILDFIELD RECORD</strong><p>${meta.runs} expeditions · ${meta.wins} dragon victories<br>Best level ${meta.bestLevel} · ${meta.discoveries.length}/4 biomes discovered</p><p>Lifetime records survive new expeditions.</p></div></div>`,true)},map(){if(!game)return;this.open('map',this.head('A WORLD WORTH WANDERING','Wildfield atlas')+`<div class="map-wrap"><canvas id="mapCanvas" width="480" height="480"></canvas></div><div class="map-legend"><span><i style="background:#f6edc9"></i>You</span><span><i style="background:#e6b979"></i>Camp</span><span><i style="background:#c2a5eb"></i>Ancient altar · 42, 24</span><span><i style="background:#283d34"></i>Mine · 38, 48</span></div><p style="text-align:center;font-size:11px">${escapeHTML(seed)} · ${Math.floor(game.p.x)}, ${Math.floor(game.p.y)}, ${Math.floor(game.p.z)}<br>North is up. The wilderness ends at the fog-bound cliffs.</p>`);drawMap()},end(win){releasePointer();state=win?'victory':'dead';previousState=state;held.visible=false;const s=game.stats;this.open(state,this.head(win?'THE WILDERNESS REMEMBERS':'EVERY LEGEND STARTS SOMEWHERE',win?'Keeper of the wild.':'Back to the earth.',win?'continueAfterWin()':'goTitle()')+`<div class="end-icon">${win?'✦':'◇'}</div><p>${win?'The sky is quiet again. The Verdant Wyrm has fallen, and this little world is yours to shape. Your story doesn’t have to end here.':`${escapeHTML(game.deathCause)} ended this expedition. What you learned—and your lifetime records—will stay with you.`}</p><div class="end-stats"><div class="stat"><b>${game.day}</b><small>DAYS EXPLORED</small></div><div class="stat"><b>${Math.floor(game.elapsed/60)}m ${Math.floor(game.elapsed%60)}s</b><small>TIME IN THE WILD</small></div><div class="stat"><b>${game.level}</b><small>ADVENTURER LEVEL</small></div><div class="stat"><b>${s.mined}</b><small>BLOCKS MINED</small></div><div class="stat"><b>${s.placed}</b><small>BLOCKS PLACED</small></div><div class="stat"><b>${s.kills}</b><small>CREATURES DEFEATED</small></div></div><div class="menu-stack">${win?'<button class="primary" onclick="continueAfterWin()">Keep building your world <span>→</span></button>':'<button class="primary" onclick="newGame()">Try this wilderness again <span>→</span></button>'}<button class="secondary" onclick="goTitle()">Return to title</button></div>`);if(!win)safeStore.del('vw-save')}};
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function inventoryClick(i){if(selectedInv<0){selectedInv=i;sound('click')}else if(selectedInv===i){selectedInv=-1}else{let a=game.inv[selectedInv];game.inv[selectedInv]=game.inv[i];game.inv[i]=a;selectedInv=-1;sound('place')}UI.renderInventory();saveGame()}
function inventoryEquip(e,i){e.preventDefault();selectedInv=i;equipSelected()}
function equipSelected(){if(selectedInv<0)return;let a=game.inv[game.sel];game.inv[game.sel]=game.inv[selectedInv];game.inv[selectedInv]=a;selectedInv=-1;UI.renderInventory();sound('click');saveGame()}
function drawMap(){const c=$('mapCanvas'),ctx=c.getContext('2d'),size=6;for(let x=0;x<W;x++)for(let z=0;z<W;z++){let y=groundAt(x,z),b=getB(x,y-1,z),water=getB(x,SEA,z)===13;ctx.fillStyle=water?'#6b9997':shade(['#81995b','#c7b77b','#d0d9c5','#4e7550'][biomeAt(x,z)],.75+heights[x+z*W]/40);ctx.fillRect(x*size,z*size,size,size)}ctx.fillStyle='#263d32';ctx.fillRect(37*6,35*6,4*6,14*6);ctx.strokeStyle='#c5d6b126';for(let i=0;i<=80;i+=10){ctx.beginPath();ctx.moveTo(i*6,0);ctx.lineTo(i*6,480);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i*6);ctx.lineTo(480,i*6);ctx.stroke()}function mark(x,z,color,text){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x*6,z*6,5,0,Math.PI*2);ctx.fill();ctx.font='10px monospace';ctx.fillStyle='#182f24';ctx.fillText(text,x*6+8,z*6+4)}mark(42.5,24.5,'#c2a5eb','ALTAR');mark(game.home.x,game.home.z,'#efc483','HOME');ctx.save();ctx.translate(game.p.x*6,game.p.z*6);ctx.rotate(-game.p.yaw);ctx.fillStyle='#fff3d2';ctx.strokeStyle='#203a2a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(6,6);ctx.lineTo(0,3);ctx.lineTo(-6,6);ctx.closePath();ctx.stroke();ctx.fill();ctx.restore();ctx.font='bold 11px monospace';ctx.fillStyle='#eef2d4';ctx.fillText('N ↑',17,24)}

let decorInstances={};
function batchDecor(){let entries=new Map();decorInstances={};decor.updateMatrixWorld(true);for(const flower of decor.children){let key=Math.floor(flower.position.x)+','+Math.floor(flower.position.y)+','+Math.floor(flower.position.z);for(const m of flower.children){let name=m.material.color.getHexString();if(!entries.has(name))entries.set(name,[]);entries.get(name).push({matrix:m.matrixWorld.clone(),key,material:m.material})}}clearGroup(decor);for(const arr of entries.values()){let mesh=new THREE.InstancedMesh(cubeGeo,arr[0].material,arr.length);arr.forEach((entry,i)=>{mesh.setMatrixAt(i,entry.matrix);(decorInstances[entry.key]||(decorInstances[entry.key]=[])).push({mesh,index:i})});mesh.instanceMatrix.needsUpdate=true;decor.add(mesh)}}
function removeDecorAt(x,y,z){let entries=decorInstances[`${x},${y},${z}`];if(!entries)return;const zero=new THREE.Matrix4().makeScale(0,0,0);for(const e of entries){e.mesh.setMatrixAt(e.index,zero);e.mesh.instanceMatrix.needsUpdate=true}delete decorInstances[`${x},${y},${z}`]}
